files.content:
:root {
  --bg: #f4f1ea;
  --card-bg: #ffffff;
  --text: #1e2a3a;
  --accent: #2a6f97;
  --accent-dark: #1f5372;
  --accent-light: #d6e6f2;
  --success: #2e7d32;
  --border: #cbd5e1;
  --radius: 12px;
  --shadow: 0 4px 12px rgba(0, 0, 0, 0.08);
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  width: 100%;
  max-width: 640px;
}

h1 {
  margin: 0 0 16px;
  font-size: 1.75rem;
  color: var(--accent-dark);
}

h2 {
  margin: 24px 0 12px;
  font-size: 1.25rem;
  color: var(--accent-dark);
}

.form-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: end;
}

.form-row label {
  flex: 1 1 100%;
  font-weight: 600;
  font-size: 0.9rem;
}

.form-row input {
  flex: 1 1 140px;
  padding: 10px 12px;
  border: 2px solid var(--border);
  border-radius: 8px;
  font-size: 1rem;
  font-family: inherit;
  transition: border-color 0.15s;
}

.form-row input:focus {
  outline: 3px solid var(--accent);
  outline-offset: 1px;
  border-color: var(--accent);
}

button {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 10px 18px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
}

button:hover {
  background: var(--accent-dark);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.97);
}

.book-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.book-item {
  border: 2px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  background: #fafafa;
}

.book-item.finished {
  border-color: var(--success);
  background: #f0f9f0;
}

.book-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 4px;
  margin-bottom: 8px;
}

.book-title {
  font-weight: 700;
  font-size: 1.1rem;
  word-break: break-word;
}

.book-pages {
  font-size: 0.9rem;
  color: #555;
}

.progress-track {
  height: 16px;
  background: var(--accent-light);
  border-radius: 8px;
  overflow: hidden;
  margin: 8px 0;
}

.progress-fill {
  height: 100%;
  width: 0%;
  background: var(--accent);
  border-radius: 8px;
  transition: width 0.3s ease;
}

.book-item.finished .progress-fill {
  background: var(--success);
}

.progress-text {
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.log-form {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: end;
}

.log-form label {
  flex: 1 1 100%;
  font-size: 0.85rem;
  font-weight: 600;
}

.log-form input {
  flex: 1 1 100px;
  padding: 8px 10px;
  border: 2px solid var(--border);
  border-radius: 8px;
  font-size: 0.95rem;
  font-family: inherit;
}

.log-form input:focus {
  outline: 3px solid var(--accent);
  outline-offset: 1px;
  border-color: var(--accent);
}

.log-form button {
  padding: 8px 14px;
  font-size: 0.95rem;
}

.finished-badge {
  display: inline-block;
  background: var(--success);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  margin-left: 8px;
  vertical-align: middle;
}

#empty-message {
  color: #666;
  font-style: italic;
}

@media (max-width: 480px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .form-row input {
    flex: 1 1 100%;
  }
  .log-form input {
    flex: 1 1 100%;
  }
}

(function () {
  'use strict';

  const books = [];
  let nextId = 1;

  const addForm = document.getElementById('add-book-form');
  const titleInput = document.getElementById('book-title');
  const pagesInput = document.getElementById('book-pages');
  const bookList = document.getElementById('book-list');
  const emptyMessage = document.getElementById('empty-message');

  function updateEmptyMessage() {
    emptyMessage.hidden = books.length > 0;
  }

  function createProgressBar(percent) {
    const track = document.createElement('div');
    track.className = 'progress-track';
    track.setAttribute('role', 'progressbar');
    track.setAttribute('aria-valuemin', '0');
    track.setAttribute('aria-valuemax', '100');
    track.setAttribute('aria-valuenow', String(percent));
    track.setAttribute('aria-label', 'Reading progress');

    const fill = document.createElement('div');
    fill.className = 'progress-fill';
    fill.style.width = percent + '%';
    track.appendChild(fill);
    return track;
  }

  function renderBook(book) {
    const li = document.createElement('li');
    li.className = 'book-item' + (book.finished ? ' finished' : '');
    li.dataset.id = String(book.id);

    const percent = Math.min(100, Math.round((book.pagesRead / book.totalPages) * 100));

    const header = document.createElement('div');
    header.className = 'book-header';

    const titleSpan = document.createElement('span');
    titleSpan.className = 'book-title';
    titleSpan.textContent = book.title;

    if (book.finished) {
      const badge = document.createElement('span');
      badge.className = 'finished-badge';
      badge.textContent = 'Finished';
      titleSpan.appendChild(badge);
    }

    const pagesSpan = document.createElement('span');
    pagesSpan.className = 'book-pages';
    pagesSpan.textContent = book.pagesRead + ' / ' + book.totalPages + ' pages';

    header.appendChild(titleSpan);
    header.appendChild(pagesSpan);
    li.appendChild(header);

    li.appendChild(createProgressBar(percent));

    const progressText = document.createElement('div');
    progressText.className = 'progress-text';
    progressText.textContent = percent + '% read';
    li.appendChild(progressText);

    if (!book.finished) {
      const form = document.createElement('form');
      form.className = 'log-form';
      form.setAttribute('aria-label', 'Log pages for ' + book.title);

      const label = document.createElement('label');
      label.textContent = 'Pages read now';
      const inputId = 'log-' + book.id;
      label.setAttribute('for', inputId);

      const input = document.createElement('input');
      input.type = 'number';
      input.id = inputId;
      input.min = '1';
      input.max = String(book.totalPages - book.pagesRead);
      input.step = '1';
      input.required = true;
      input.placeholder = 'e.g. 20';

      const btn = document.createElement('button');
      btn.type = 'submit';
      btn.textContent = 'Log pages';

      form.appendChild(label);
      form.appendChild(input);
      form.appendChild(btn);

      form.addEventListener('submit', function (e) {
        e.preventDefault();
        const amount = parseInt(input.value, 10);
        if (!amount || amount < 1) {
          input.focus();
          return;
        }
        const remaining = book.totalPages - book.pagesRead;
        if (amount > remaining) {
          input.value = String(remaining);
          input.focus();
          return;
        }
        book.pagesRead += amount;
        if (book.pagesRead >= book.totalPages) {
          book.pagesRead = book.totalPages;
          book.finished = true;
        }
        renderAll();
      });

      li.appendChild(form);
    }

    return li;
  }

  function renderAll() {
    bookList.innerHTML = '';
    books.forEach(function (book) {
      bookList.appendChild(renderBook(book));
    });
    updateEmptyMessage();
  }

  addForm.addEventListener('submit', function (e) {
    e.preventDefault();
    const title = titleInput.value.trim();
    const totalPages = parseInt(pagesInput.value, 10);
    if (!title || !totalPages || totalPages < 1) {
      return;
    }
    books.push({
      id: nextId++,
      title: title,
      totalPages: totalPages,
      pagesRead: 0,
      finished: false
    });
    titleInput.value = '';
    pagesInput.value = '';
    titleInput.focus();
    renderAll();
  });

  updateEmptyMessage();
})();
